"""Build contract `Signal` documents from strategy outputs (built-in or rule-builder)."""
from __future__ import annotations

import math
from datetime import datetime, timezone

import numpy as np
import pandas as pd

from app.backtesting.engine import BacktestConfig, run_backtest
from app.indicators import core
from app.strategies.base import STRENGTH_METHOD, BuiltinStrategy, StrategyOutput, label_for, score_conditions

DISCLAIMER = (
    "Educational analysis generated by deterministic rules on {source} data. Not investment advice and not a "
    "recommendation to buy or sell any security. Simulated prices are not real NSE/BSE prices."
)
ATR_STOP_MULT = 2.0
ATR_TARGET_MULT = 3.0
DEFAULT_CAPITAL = 100000.0
DEFAULT_RISK_PCT = 1.0


def _num(x) -> float | None:
    if x is None:
        return None
    try:
        f = float(x)
    except (TypeError, ValueError):
        return None
    return None if math.isnan(f) or math.isinf(f) else round(f, 4)


def iso_from_ts(ts: int) -> str:
    return datetime.fromtimestamp(int(ts), tz=timezone.utc).isoformat()


def historical_performance(df: pd.DataFrame, out: StrategyOutput, timeframe: str) -> dict | None:
    n = len(df)
    if n < 30:
        return None
    entries, exits = out.entries(n), out.exits(n)
    bt = run_backtest(df, entries, exits, BacktestConfig())
    trades = bt.trades
    wins = [t for t in trades if t.pnl > 0]
    start = datetime.fromtimestamp(int(df["time"].iloc[0]), tz=timezone.utc).date().isoformat()
    end = datetime.fromtimestamp(int(df["time"].iloc[-1]), tz=timezone.utc).date().isoformat()
    return {
        "trades": len(trades),
        "win_rate": round(100.0 * len(wins) / len(trades), 2) if trades else None,
        "avg_return_pct": round(float(np.mean([t.pnl_pct for t in trades])), 4) if trades else None,
        "lookback": f"{n} {timeframe} bars ({start} to {end})",
        "note": ("Causal backtest of the same rules on this instrument's stored history, after default costs and "
                 "slippage. Past simulated outcomes are descriptive only and are NOT a probability of future success."),
    }


def build_signal(
    *, df: pd.DataFrame, out: StrategyOutput, symbol: str, exchange: str, strategy_name: str, strategy_key: str,
    timeframe: str, data_source: str, capital: float | None = None, risk_per_trade_pct: float | None = None,
    stop_loss_pct: float | None = None, take_profit_pct: float | None = None, include_history: bool = True,
) -> dict:
    n = len(df)
    if n == 0:
        raise ValueError("No bars available")
    i = n - 1
    capital = float(capital or DEFAULT_CAPITAL)
    risk_pct = float(risk_per_trade_pct or DEFAULT_RISK_PCT)
    entries, exits = out.entries(n), out.exits(n)
    price = float(df["close"].iloc[i])
    action = "BUY" if entries[i] else "SELL" if exits[i] else "HOLD"

    conds = out.sell if action == "SELL" else out.buy
    score, comps = score_conditions(conds, i)
    conditions = [
        {"description": tag + c.description + ("" if c.required else " (optional)"),
         "satisfied": bool(np.asarray(c.satisfied)[i]), "value": c.value_at(i)}
        for tag, group in (("[BUY] ", out.buy), ("[SELL] ", out.sell)) for c in group
    ]

    atr_arr = core.atr(df["high"].to_numpy(float), df["low"].to_numpy(float), df["close"].to_numpy(float), 14)
    atr_v = _num(atr_arr[i]) if n else None
    ind_values: dict[str, float | None] = {k: _num(np.asarray(v)[i]) for k, v in out.indicators.items()}
    ind_values["atr_14"] = atr_v

    stop_loss = take_profit = rr = None
    position = None
    if action == "BUY":
        if stop_loss_pct:
            stop_loss = price * (1 - stop_loss_pct / 100.0)
        elif atr_v:
            stop_loss = price - ATR_STOP_MULT * atr_v
        if take_profit_pct:
            take_profit = price * (1 + take_profit_pct / 100.0)
        elif atr_v:
            take_profit = price + ATR_TARGET_MULT * atr_v
        if stop_loss is not None and stop_loss <= 0:
            stop_loss = None
        if stop_loss is not None and take_profit is not None and price > stop_loss:
            rr = (take_profit - price) / (price - stop_loss)
        if stop_loss is not None and price > stop_loss:
            per_share = price - stop_loss
            qty = int(math.floor(capital * risk_pct / 100.0 / per_share))
            qty = max(0, min(qty, int(capital // price)))
            position = {
                "quantity": qty, "capital_required": round(qty * price, 2),
                "capital_at_risk": round(qty * per_share, 2), "risk_per_trade_pct": risk_pct,
                "assumed_capital": capital,
            }

    insufficient = n <= out.warmup_bars
    met = [c.description for c in conds if bool(np.asarray(c.satisfied)[i])]
    unmet = [c.description for c in conds if c.required and not bool(np.asarray(c.satisfied)[i])]
    if action == "BUY":
        expl = (f"{strategy_name} entry triggered on the {timeframe} bar closing at {price:.2f}: "
                + "; ".join(met) + ". ")
        if stop_loss is not None:
            expl += (f"Illustrative risk plan: stop {stop_loss:.2f}"
                     + (f" ({ATR_STOP_MULT:g}x ATR)" if not stop_loss_pct else f" ({stop_loss_pct:g}%)")
                     + (f", target {take_profit:.2f}" if take_profit is not None else "") + ". ")
    elif action == "SELL":
        expl = (f"{strategy_name} exit condition met at {price:.2f}: " + "; ".join(met)
                + ". The engine is long-only, so SELL means 'exit / avoid a long position', not a short sale. ")
    else:
        expl = (f"No {strategy_name} entry or exit on the latest {timeframe} bar (close {price:.2f}). "
                + (f"Entry conditions not met: {'; '.join(unmet)}. " if unmet else ""))
    if insufficient:
        expl += f"Only {n} bars available; this strategy needs about {out.warmup_bars} bars of warm-up, so indicators may be incomplete. "
    expl += f"Strength {score:.0f}/100 ({label_for(score)}) is a rule-margin score, not a probability."

    return {
        "id": None, "symbol": symbol, "exchange": exchange, "strategy": strategy_name, "strategy_key": strategy_key,
        "timeframe": timeframe, "timestamp": iso_from_ts(int(df["time"].iloc[i])), "data_source": data_source,
        "action": action, "price": round(price, 4), "entry_conditions": out.entry_text, "exit_conditions": out.exit_text,
        "indicator_values": ind_values, "conditions": conditions,
        "stop_loss": _num(stop_loss), "take_profit": _num(take_profit), "risk_reward": _num(rr),
        "position_size": position,
        "strength": {"score": score, "label": label_for(score), "method": STRENGTH_METHOD, "components": comps},
        "historical_performance": historical_performance(df, out, timeframe) if include_history else None,
        "explanation": expl.strip(),
        "disclaimer": DISCLAIMER.format(source=data_source),
    }


def builtin_signal(strategy: BuiltinStrategy, df: pd.DataFrame, params: dict | None, **kw) -> dict:
    out = strategy.run(df, params)
    return build_signal(df=df, out=out, strategy_name=strategy.name, strategy_key=strategy.key, **kw)
